package dk.stream.android;
import org.junit.Test;
import static org.junit.Assert.*;
public class FavoriteListsTest {
 private LocalMedia local(String name){return new LocalMedia("content://local/"+name.replace(" ",""),name,"audio/mpeg",false);}
 @Test public void existingFavoritesMigrateWithoutLosingEntries(){Library library=new Library();Library.Source source=Library.Source.m3u("Test","https://example.com/list");library.sources.add(source);library.favorites.add(new Library.Entry(source.id,new Playlist.Channel("TV","https://example.com/tv","")));library.addRadio(new RadioStation("r","Radio","https://example.com/radio",""));library.toggleLocalFavorite(local("Anders og Anders.mp3"));library.toggleLocalFavorite(local("Musik.mp3"));assertEquals(1,FavoriteLists.items(library,"Streaming").size());assertEquals(1,FavoriteLists.items(library,"Radio").size());assertEquals(1,FavoriteLists.items(library,"Podcast").size());assertEquals(1,FavoriteLists.items(library,"Musik").size());}
 @Test public void localAndPcloudShareListsAndPersist()throws Exception{Library library=new Library();FavoriteLists.Item local=FavoriteLists.of(local("Song.mp3"));FavoriteLists.Item cloud=FavoriteLists.of(new LocalMedia("content://dk.stream.android.pcloud/account?url=file","Episode.mp3","audio/mpeg",false));FavoriteLists.assign(library,local,"Podcast");FavoriteLists.assign(library,cloud,"Podcast");Library restored=Library.fromJson(library.toJson());assertEquals(2,FavoriteLists.items(restored,"Podcast").size());assertTrue(FavoriteLists.items(restored,"Musik").isEmpty());}
 @Test public void anySourceCanBeAssignedAndMovedWithoutDuplication(){Library library=new Library();FavoriteLists.Item radio=FavoriteLists.of(new RadioStation("r","Radio","https://example.com/radio",""));FavoriteLists.assign(library,radio,"Podcast");assertEquals(1,FavoriteLists.items(library,"Podcast").size());FavoriteLists.assign(library,radio,"Musik");assertTrue(FavoriteLists.items(library,"Podcast").isEmpty());assertEquals(1,library.radioFavorites.size());FavoriteLists.remove(library,radio);assertTrue(library.radioFavorites.isEmpty());assertTrue(library.favoriteAssignments.isEmpty());}
 @Test public void streamingKeepsTvFilmAndSeries(){Library library=new Library();Library.Source source=Library.Source.m3u("Test","https://example.com/list");library.sources.add(source);for(Playlist.Kind kind:Playlist.Kind.values())FavoriteLists.assign(library,FavoriteLists.of(new Library.Entry(source.id,new Playlist.Channel(kind.name(),"https://example.com/"+kind,"",kind,null))),"Streaming");assertEquals(3,FavoriteLists.items(library,"Streaming").size());for(int i=0;i<3;i++)assertEquals(Playlist.Kind.values()[i],FavoriteLists.items(library,"Streaming").get(i).kind());}
 @Test public void backupIncludesAssignments()throws Exception{Library library=new Library();FavoriteLists.assign(library,FavoriteLists.of(local("Song.mp3")),"Podcast");Library restored=SettingsBackup.decode(new java.io.ByteArrayInputStream(SettingsBackup.encode(library)));assertEquals(1,FavoriteLists.items(restored,"Podcast").size());}
 @Test(expected=IllegalArgumentException.class)public void unknownListIsRejected(){FavoriteLists.assign(new Library(),FavoriteLists.of(local("Song.mp3")),"Invalid");}
 @Test public void renamedRadioKeepsItsListAndOrderSurvivesBackup()throws Exception{Library library=new Library();FavoriteLists.Item one=FavoriteLists.of(new RadioStation("one","One","https://example.com/one","")),two=FavoriteLists.of(new RadioStation("two","Two","https://example.com/two",""));FavoriteLists.assign(library,one,"Radio");FavoriteLists.assign(library,two,"Radio");FavoriteLists.move(library,"Radio",two,-1);library.renameRadio("two","Renamed");Library restored=Library.fromJson(library.toJson());assertEquals("Renamed",FavoriteLists.items(restored,"Radio").get(0).name());assertEquals(2,FavoriteLists.items(restored,"Radio").size());}

 @Test public void sourceRefreshKeepsChosenListWhenStreamUrlChanges(){Library library=new Library();Library.Source source=Library.Source.m3u("Test","https://example.com/list");library.sources.add(source);Library.Entry old=new Library.Entry(source.id,new Playlist.Channel("Channel","https://example.com/old",""));FavoriteLists.assign(library,FavoriteLists.of(old),"Podcast");library.refreshFavorites(source.id,java.util.Arrays.asList(new Playlist.Channel("Channel","https://example.com/new","")));assertEquals(1,FavoriteLists.items(library,"Podcast").size());assertEquals("https://example.com/new",FavoriteLists.items(library,"Podcast").get(0).stream.channel.url);library.removeSource(source.id);assertTrue(library.favoriteAssignments.isEmpty());}

 @Test public void favoritesHomeStartupChoiceSurvivesBackup()throws Exception{Library library=new Library();library.favoritesOnStart=true;library.setFavoritesStartTab(6);Library restored=SettingsBackup.decode(new java.io.ByteArrayInputStream(SettingsBackup.encode(library)));assertTrue(restored.favoritesOnStart);assertEquals(6,restored.favoritesStartTab);}

}
